    'gate.employeeQuestion': '¿Eres empleado/a, no el/la propietario/a?', 'gate.employeeBody': 'No hace falta que sigas los pasos: pide a tu jefe/a que te diga la Clave de API y la URL de la base de datos que él/ella configuró (las puede ver en Nube → "Cambiar la configuración de Firebase"), pégalas en el formulario de abajo y pulsa "Guardar y conectar". Listo.',
    'gate.cloudIntro': 'Cada negocio tiene su <strong>propio espacio en la nube</strong> (gratuito, de Google), separado del resto. <strong>Este paso es obligatorio</strong>: sin él, cada dispositivo (el móvil del camarero, la tablet de cocina, tu ordenador) guardaría sus datos por separado y no se verían entre sí — las comandas de Sala no llegarían a Cocina, el chat no se compartiría, y las tareas que asignes no las vería tu equipo en su dispositivo. Configurarlo lleva 2 minutos y solo hay que hacerlo una vez.',
    'gate.seeFullGuide': '¿No tienes esos datos? Ver guía completa (para el propietario)',
    'gate.followSteps': 'Sigue estos pasos:', 'gate.shareWithEmployees': '¿Vas a compartir esto con empleados? Lee esto',
    'gate.businesses': 'Negocios', 'gate.setupCloud': 'Configura tu nube', 'gate.cloudStepLabel': 'Paso 2 de 3 — Conecta tu nube (≈10 minutos, una sola vez)',
    'gate.nt.step1Title': 'Crea una cuenta gratis en Netlify', 'gate.nt.step1Body': 'Abre <code>www.netlify.com</code> en otra pestaña y pulsa <strong>"Sign up"</strong>. Puedes entrar con tu cuenta de Google. Es gratis y no pide tarjeta.',
    'gate.nt.step2Title': 'Ten los dos archivos juntos en una carpeta', 'gate.nt.step2Body': 'En una carpeta de tu ordenador deja <strong>los dos archivos</strong> de GastroGoan: <code>index.html</code> y <code>reservagastrogoan.html</code>. <strong>No renombres</strong> ninguno de los dos.',
    'gate.nt.step3Title': 'Arrastra la carpeta a Netlify', 'gate.nt.step3Body': 'En Netlify, ve a <strong>"Sites"</strong> y arrastra tu carpeta al recuadro <strong>"Drag and drop your site output folder here"</strong> (o "Deploys" → "Deploy manually").',
    'gate.nt.step4Title': 'Copia la dirección que te da', 'gate.nt.step4Body': 'En unos segundos Netlify publica el sitio y te da una dirección tipo <code>https://tu-sitio.netlify.app</code>. Puedes cambiar el nombre en "Site settings" → "Change site name".',
    'gate.nt.step5Title': 'Abre SIEMPRE la app desde esa dirección', 'gate.nt.step5Body': 'A partir de ahora gestiona la app desde <code>https://tu-sitio.netlify.app</code>. Al llamarse index.html, se abre directamente. Solo así el QR de reservas y pedidos funcionará de verdad para tus clientes.',
    'gate.nt.goodTitle': '¡Bien!', 'gate.nt.hostedBody': 'Estás abriendo la app desde una dirección pública (<code>${host}</code>). El QR de reservas ya puede funcionar. Si es tu sitio de Netlify, ya está todo listo.',
    'gate.nt.notHostedBody': 'Ahora mismo estás abriendo la app <strong>desde un archivo local</strong>, no desde la dirección oficial de GastroGoan. Las reservas/pedidos por QR <strong>no funcionarán</strong> hasta que abras la app desde la dirección web que te dimos al comprarla.',
    'gate.nt.title': 'Abre la app desde su dirección web', 'gate.nt.stepLabel': '',
    'gate.nt.explain': '',
    'gate.nt.doneBtn': 'Entendido — Continuar',
