    'mn.comandas.howItWorksTitle': 'Com funciona?', 'mn.comandas.howItWorks1': 'Cada vegada que "s\'envia" un plat a cuina o barra, s\'obre automàticament una petita finestra amb el val i es llança el diàleg d\'impressió del teu navegador — no cal cap programa addicional.',
    'mn.comandas.howItWorks2': 'Cada perfil d\'impressora d\'aquí sota correspon a un dispositiu/pestanya amb la seva pròpia impressora predeterminada: configura\'n un per a cada punt físic on tinguis una impressora tèrmica connectada (cuina, barra, sala...), i indica què ha d\'imprimir cadascun.',
    'mn.comandas.howItWorks3': 'Truc: configura aquesta impressora com a predeterminada al dispositiu on la facis servir perquè cada val s\'imprimeixi sol, sense haver de triar-la cada vegada. Usa el botó "Provar impressió" de cada perfil abans de començar a treballar amb clients.',
