    'mn.pedidos.minOrder': 'Comanda mínima (€)', 'mn.pedidos.minOrderDesc': 'Import mínim de la comanda (sense comptar l\'enviament) per poder-la fer en línia. Posa 0 per no exigir mínim.',
    'mn.pedidos.allowPayOnPickup': 'Permetre "pagar en recollir / en rebre"',
