    'mn.pedidos.radiusDesc': '0 = no distance limit. Requires your business "Address" (Contact section) to be filled in.',
    'mn.pedidos.locationCalculated': 'Calculated location',
    'mn.pedidos.matchExplain': 'A delivery order is accepted if the customer\'s postal code is on your list, or their address is within the configured radius (meeting either condition is enough).',
    'mn.redsys.title': 'Online card payment (virtual POS)',
    'mn.redsys.desc': 'Let your customers pay by card when placing an online order (takeaway/delivery). Payment goes through your own bank\'s virtual POS (Redsys): the money goes directly to your account, with no intermediaries.',
    'mn.redsys.checking': 'Checking configuration...', 'mn.redsys.merchantCode': 'Merchant code (FUC)', 'mn.redsys.terminal': 'Terminal',
    'mn.redsys.secretKey': 'Secret key (Signature)', 'mn.redsys.secretKeyPh': 'Paste it here (won\'t be shown again)',
    'mn.redsys.secretKeyHint': 'You get this from your virtual POS admin panel on your bank\'s website.',
    'mn.redsys.realEnv': 'Live environment (real charges). Unchecked = test mode.', 'mn.redsys.configured': 'Configured',
    'mn.redsys.environment': 'Environment', 'mn.redsys.envReal': 'live', 'mn.redsys.envTest': 'test',
    'gate.employeeQuestion': 'Are you an employee, not the owner?', 'gate.employeeBody': 'You don\'t need to follow the steps: ask your boss for the API Key and the database URL they set up (they can see them under Cloud → "Change Firebase settings"), paste them into the form below and click "Save and connect". Done.',
    'gate.cloudIntro': 'Each business has its <strong>own space in the cloud</strong> (free, from Google), separate from everyone else\'s. <strong>This step is mandatory</strong>: without it, each device (the waiter\'s phone, the kitchen tablet, your computer) would store its data separately and wouldn\'t see each other\'s — Floor orders wouldn\'t reach the Kitchen, chat wouldn\'t be shared, and tasks you assign wouldn\'t show up on your team\'s device. It takes 2 minutes to set up and only needs to be done once.',
    'gate.seeFullGuide': 'Don\'t have that data? See the full guide (for the owner)',
    'gate.followSteps': 'Follow these steps:', 'gate.shareWithEmployees': 'Will you share this with employees? Read this',
    'gate.businesses': 'Businesses', 'gate.setupCloud': 'Set up your cloud', 'gate.cloudStepLabel': 'Step 2 of 3 — Connect your cloud (≈10 minutes, one time only)',
    'gate.nt.step1Title': 'Create a free Netlify account', 'gate.nt.step1Body': 'Open <code>www.netlify.com</code> in another tab and click <strong>"Sign up"</strong>. You can sign in with your Google account. It\'s free and doesn\'t ask for a card.',
    'gate.nt.step2Title': 'Keep both files together in a folder', 'gate.nt.step2Body': 'In a folder on your computer, keep <strong>both GastroGoan files</strong>: <code>index.html</code> and <code>reservagastrogoan.html</code>. <strong>Don\'t rename</strong> either of them.',
    'gate.nt.step3Title': 'Drag the folder to Netlify', 'gate.nt.step3Body': 'On Netlify, go to <strong>"Sites"</strong> and drag your folder onto the <strong>"Drag and drop your site output folder here"</strong> box (or "Deploys" → "Deploy manually").',
    'gate.nt.step4Title': 'Copy the address it gives you', 'gate.nt.step4Body': 'Within a few seconds Netlify publishes the site and gives you an address like <code>https://your-site.netlify.app</code>. You can change the name under "Site settings" → "Change site name".',
    'gate.nt.step5Title': 'ALWAYS open the app from that address', 'gate.nt.step5Body': 'From now on manage the app from <code>https://your-site.netlify.app</code>. Since it\'s named index.html, it opens directly. Only this way will the reservations/orders QR really work for your customers.',
    'gate.nt.goodTitle': 'Great!', 'gate.nt.hostedBody': 'You are opening the app from a public address (<code>${host}</code>). The reservations QR can already work. If this is your Netlify site, everything is ready.',
    'gate.nt.notHostedBody': 'Right now you are opening the app <strong>from a local file</strong>, not from GastroGoan\'s official address. Reservations/orders via QR <strong>will not work</strong> until you open the app from the web address you were given when you bought it.',
    'gate.nt.title': 'Open the app from its web address', 'gate.nt.stepLabel': '',
    'gate.nt.explain': 'The management app works fine open in your browser, but the <strong>reservations and online orders QR</strong> only works if you upload both files to a free public host like <strong>Netlify</strong>. You have the full tutorial in <strong>tutorial-netlify.html</strong> (next to the app).',
    'gate.nt.doneBtn': 'Understood — Continue',
