    'gate.cloudModalTitle': 'Cloud — Sync between devices', 'gate.needLicenseForCloud': 'Activate your GastroGoan license to connect this device to the cloud.',
    'gate.licenseActivatedFor': 'License activated for', 'gate.tenMinutesIntro': 'It will take about 10 minutes, one time only. Follow the step-by-step guide and then paste here the two values it asks for at the end:',
    'gate.miniStep1': 'Create a free project at <code>console.firebase.google.com</code>', 'gate.miniStep2': 'Enable <strong>Realtime Database</strong>',
